```go
// CustomHeaderMatcher determines which HTTP headers get mapped to gRPC metadata
func CustomHeaderMatcher(key string) (string, bool) {
	switch key {
	// Pass specific headers through as exact gRPC metadata keys
	case "X-User-Id", "X-Request-Id", "Authorization":
		return key, true

	// Default behavior: let grpc-gateway use its standard matching (prefixes with 'grpcgateway-')
	default:
		return runtime.DefaultHeaderMatcher(key)
	}
}
```

